ALTER TABLE public.lists DROP CONSTRAINT lists_kind_check;
ALTER TABLE public.lists ADD CONSTRAINT lists_kind_check CHECK(kind IN ('movies','music','books','art','mixed'));
ALTER TABLE public.list_items DROP CONSTRAINT list_items_media_type_check;
ALTER TABLE public.list_items ADD CONSTRAINT list_items_media_type_check CHECK(media_type IN ('movie','music','book','art'));
ALTER TABLE public.profiles ADD COLUMN cultural_top_five jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.profiles ADD COLUMN city text NOT NULL DEFAULT 'Ciudad de Buenos Aires';
ALTER TABLE public.profiles ADD COLUMN city_configured boolean NOT NULL DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN event_interests text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.activity ADD COLUMN category text;
UPDATE public.activity a SET category = i.media_type FROM public.list_items i WHERE a.item_id=i.id;
UPDATE public.activity SET category='movie' WHERE category IS NULL AND source IN ('tmdb','imdb');
UPDATE public.activity a SET category=CASE l.kind WHEN 'movies' THEN 'movie' WHEN 'books' THEN 'book' WHEN 'music' THEN 'music' WHEN 'art' THEN 'art' ELSE NULL END FROM public.lists l WHERE a.list_id=l.id AND a.category IS NULL;
CREATE FUNCTION public.set_activity_category() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.category IS NULL THEN IF NEW.item_id IS NOT NULL THEN SELECT media_type INTO NEW.category FROM public.list_items WHERE id=NEW.item_id; ELSIF NEW.source IN ('tmdb','imdb') THEN NEW.category='movie'; ELSIF NEW.source='itunes' THEN NEW.category='music'; ELSIF NEW.source='openlibrary' THEN NEW.category='book'; ELSIF NEW.list_id IS NOT NULL THEN SELECT CASE kind WHEN 'movies' THEN 'movie' WHEN 'books' THEN 'book' WHEN 'music' THEN 'music' WHEN 'art' THEN 'art' ELSE NULL END INTO NEW.category FROM public.lists WHERE id=NEW.list_id; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER classify_activity BEFORE INSERT ON public.activity FOR EACH ROW EXECUTE FUNCTION public.set_activity_category();
CREATE TABLE public.cultural_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,media_type text NOT NULL CHECK(media_type IN ('music','book')),source text NOT NULL,external_id text NOT NULL,title text NOT NULL,creator text,year integer,image_url text,queued boolean NOT NULL DEFAULT false,consumed boolean NOT NULL DEFAULT false,favorite boolean NOT NULL DEFAULT false,dismissed boolean NOT NULL DEFAULT false,score_10 smallint CHECK(score_10 BETWEEN 1 AND 10),review text NOT NULL DEFAULT '' CHECK(length(review)<=3000),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,source,external_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cultural_entries TO authenticated;
GRANT ALL ON public.cultural_entries TO service_role;
ALTER TABLE public.cultural_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY culture_read ON public.cultural_entries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.are_friends(auth.uid(),user_id));
CREATE POLICY culture_insert ON public.cultural_entries FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY culture_update ON public.cultural_entries FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY culture_delete ON public.cultural_entries FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.record_culture_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at=now(); IF TG_OP='UPDATE' AND NEW.consumed IS NOT DISTINCT FROM OLD.consumed AND NEW.score_10 IS NOT DISTINCT FROM OLD.score_10 AND NEW.review IS NOT DISTINCT FROM OLD.review THEN RETURN NEW; END IF; IF NEW.consumed OR NEW.score_10 IS NOT NULL OR NEW.review<>'' THEN INSERT INTO public.activity(user_id,kind,source,external_id,title,image_url,score_10,body,category) VALUES(NEW.user_id,CASE WHEN TG_OP='INSERT' AND NEW.consumed THEN 'watched' WHEN TG_OP='UPDATE' AND NEW.consumed AND NOT OLD.consumed THEN 'watched' WHEN NEW.review<>'' THEN 'reviewed' ELSE 'rated' END,NEW.source,NEW.external_id,NEW.title,NEW.image_url,NEW.score_10,NEW.review,NEW.media_type); END IF; RETURN NEW; END $$;
CREATE TRIGGER culture_activity BEFORE INSERT OR UPDATE ON public.cultural_entries FOR EACH ROW EXECUTE FUNCTION public.record_culture_activity();
CREATE TABLE public.cultural_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,source text NOT NULL,external_id text NOT NULL,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.cultural_comments TO authenticated;
GRANT ALL ON public.cultural_comments TO service_role;
ALTER TABLE public.cultural_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY culture_comments_read ON public.cultural_comments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.are_friends(auth.uid(),user_id));
CREATE POLICY culture_comments_insert ON public.cultural_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY culture_comments_delete ON public.cultural_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.cultural_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city text NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),description text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz,venue text NOT NULL,address text,neighborhood text,interest text NOT NULL CHECK(interest IN ('music','movie','art','theater','book','festival')),price numeric CHECK(price>=0),currency text NOT NULL DEFAULT 'ARS',source_name text NOT NULL,source_url text NOT NULL,image_url text,community boolean NOT NULL DEFAULT false,created_by uuid REFERENCES public.profiles(id),verified boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(city,source_url,starts_at));
GRANT SELECT,INSERT ON public.cultural_events TO authenticated;
GRANT ALL ON public.cultural_events TO service_role;
ALTER TABLE public.cultural_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.cultural_events FOR SELECT TO authenticated USING(verified OR community OR created_by=auth.uid());
CREATE POLICY events_submit ON public.cultural_events FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND community AND NOT verified AND source_name='Comunidad');
CREATE INDEX events_city_date ON public.cultural_events(city,starts_at);
CREATE TABLE public.event_attendance(event_id uuid NOT NULL REFERENCES public.cultural_events(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,status text NOT NULL CHECK(status IN ('going','interested')),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.event_attendance TO authenticated;
GRANT ALL ON public.event_attendance TO service_role;
ALTER TABLE public.event_attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY attendance_read ON public.event_attendance FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.are_friends(auth.uid(),user_id));
CREATE POLICY attendance_insert ON public.event_attendance FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY attendance_update ON public.event_attendance FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY attendance_delete ON public.event_attendance FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.record_event_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.cultural_events; BEGIN IF TG_OP='UPDATE' AND NEW.status=OLD.status THEN RETURN NEW; END IF; SELECT * INTO e FROM public.cultural_events WHERE id=NEW.event_id; INSERT INTO public.activity(user_id,kind,source,external_id,title,image_url,body,category) VALUES(NEW.user_id,'added','event',NEW.event_id::text,e.title,e.image_url,CASE NEW.status WHEN 'going' THEN 'Voy' ELSE 'Me interesa' END,'event'); RETURN NEW; END $$;
CREATE TRIGGER attendance_activity AFTER INSERT OR UPDATE ON public.event_attendance FOR EACH ROW EXECUTE FUNCTION public.record_event_activity();
CREATE TABLE public.event_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES public.cultural_events(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,user_id));
GRANT SELECT,INSERT ON public.event_reports TO authenticated;
GRANT ALL ON public.event_reports TO service_role;
ALTER TABLE public.event_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_read_own ON public.event_reports FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY reports_submit ON public.event_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE TABLE public.culture_cache(key text PRIMARY KEY,payload jsonb NOT NULL,expires_at timestamptz NOT NULL);
GRANT SELECT ON public.culture_cache TO authenticated;
GRANT ALL ON public.culture_cache TO service_role;
ALTER TABLE public.culture_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY cache_read ON public.culture_cache FOR SELECT TO authenticated USING(true);